            {
                if(!outstanding){handle?.Dispose();if(graph!=null)UnityEngine.Object.DestroyImmediate(graph);foreach(var texture in new[]{heightTexture,hardnessTexture})if(texture!=null)UnityEngine.Object.DestroyImmediate(texture);foreach(var rt in new[]{heightRt,hardnessRt})if(rt!=null){rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
                proof.sourceBytesExact=sources.All(p=>File.Exists(Io(p.Key))&&AssetSha(p.Key)==p.Value);proof.graphAndCriticalPosesExact=JsonUtility.ToJson(world.definition.graph)==graphBefore&&critical.All(p=>Pose(p.Key)==p.Value);proof.tiles=tileProofs.Values.ToArray();if(proof.status=="IN_PROGRESS")proof.status="REJECTED_NATIVE_VISTA_POSTGRADE_INSPECT_ACTUAL_EXCEPTION";File.WriteAllText(receipt,JsonUtility.ToJson(proof,true));if(!proof.sourceBytesExact||!proof.graphAndCriticalPosesExact)throw new InvalidOperationException("Vista post-grade changed original vendor sources, graph or critical poses.");
            }
        }
    }
